(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.015+t*0.3)*11;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025+t*0.4)*8 + Math.cos(sy*0.02-t*0.15)*6;
  const w2y = Math.cos(sy*0.022+t*0.35)*7 + Math.sin(sx*0.028-t*0.25)*5;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [120+Math.sin(t*0.5)*120, 60+Math.cos(t*0.35)*40, 0.07, 2.1, 1.0],
    [360+Math.cos(t*0.45)*100, 180+Math.sin(t*0.6)*50, 0.09, 1.8, 0.8],
    [240+Math.sin(t*0.3+2)*150, 120+Math.cos(t*0.4+1)*80, 0.055, 2.4, 1.2],
    [80+Math.cos(t*0.7+1)*70, 200+Math.sin(t*0.5+3)*50, 0.11, 1.6, 0.7],
    [400+Math.sin(t*0.35+4)*80, 40+Math.cos(t*0.8+2)*60, 0.065, 2.7, 1.1],
    [240+Math.cos(t*0.28+5)*130, 220+Math.sin(t*0.48)*70, 0.08, 2.0, 0.9],
    [180+Math.sin(t*0.55+3)*90, 30+Math.cos(t*0.65+1)*55, 0.1, 1.9, 0.85],
    [320+Math.cos(t*0.4+2)*110, 100+Math.sin(t*0.55+4)*65, 0.075, 2.3, 1.05]
  ];
  let aS=0, iS=0, a2=0, i2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    const da = Math.atan2(fy-sY, fx-sX);
    const wave = Math.sin(d*f - t*sp);
    const angMod = Math.sin(da*2+t*0.5)*0.15;
    aS += (wave+angMod)*w;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    a2 += Math.sin(d*f*1.3-t*sp*0.8+2.1)*w*0.5;
    i2 += Math.sin(d*f*0.4+t*sp*0.3-0.8)*w*0.5;
  }
  const act=aS/7, inh=iS/7, act2=a2/7, inh2=i2/7;
  const bg = (Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.038+t*1.0))/2
    + Math.sin((fx+fy)*0.1+t*2.2)*0.2 + Math.sin((fx-fy)*0.09-t*1.8)*0.18
    + Math.sin(fx*0.06+fy*0.04-t*1.5)*0.12;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35
    + Math.sin(dist*0.08-ang*2-t*2.5)*0.15;
  const vfield = Math.sin(fx*0.08+t*0.6)*Math.cos(fy*0.06-t*0.4)*0.3;
  const react1 = Math.tanh((act-inh*0.65+bg*0.25+spiral*0.4+vfield)*2.0);
  const react2 = Math.tanh((act2-inh2*0.7+spiral*0.3-bg*0.15)*2.5);
  const cross = react1*react2*0.6;
  const cell = Math.tanh((Math.sin(fx*0.14)*Math.sin(fy*0.14)+Math.sin((fx+fy)*0.09+t)*0.45+Math.sin(fx*0.2-fy*0.12+t*0.7)*0.2)*1.4)*0.25;
  const micro = Math.sin(fx*0.35+fy*0.25+t*3)*Math.sin(fx*0.3-fy*0.4-t*2.5)*0.08;
  const blend = react1*0.5+react2*0.15+cross*0.1+cell*0.2+micro;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,42],[10,35,75],[12,65,105],[18,110,120],[35,155,135],
    [120,185,120],[195,200,80],[220,165,55],[215,110,60],[185,65,65],
    [140,35,75],[85,18,60],[35,12,50],[5,10,42]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.78+Math.sin(react1*Math.PI)*0.18+cross*0.08;
  const edge=Math.abs(react1)>0.65?1.12:Math.abs(react2)>0.7?1.08:0.95;
  const glow=Math.max(0,1-Math.abs(react1-react2)*2)*0.1;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0)
  ];
}
